INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-han-zhao-pingyang-309','loc-9efed331fab4b4a75a343593f53c5bed','dynasty','han-zhao','平阳',NULL,309,1,NULL,318,12,NULL,3708,3827,'year','month','primary','刘渊迁都平阳，汉赵后续君主沿用，刘曜于319年迁都长安。','[{"label":"《晋书·载记第一·刘元海》","url":"https://www.shidianguji.com/book/LS0005/chapter/LS0005_1413"},{"label":"高德地图地理编码与地点检索","url":"https://lbs.amap.com/api/webservice/guide/api/georegeo"}]');
