INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-jin-chunqiu-jiang-669','loc-274b46582b7c685b4f68d87b936312ab','dynasty','jin-chunqiu','绛',NULL,-669,1,NULL,-585,12,NULL,-8016,-6997,'year','year','primary','《史记·晋世家》记献公八年城聚、命曰绛并始都之，取前669年；《左传》庄公二十六年（前668年）另记士蒍城绛。前585年景公迁新田后称故绛。城址有绛县南城村车厢城、翼城县南梁镇故城村及曲村—天马一带等说法，翼与绛是否同址亦有争议；地点名称原注：绛（故绛）。','[{"label":"《史记》卷三十九·晋世家：翼都、曲沃封邑与献公都绛","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"运城长安网：南城村车厢城与晋献公都绛的地方志记载","url":"https://www.ycpeace.gov.cn/a/wenyuan/biaolihedong/20211112/24167.html"},{"label":"潘明娟《圣都与俗都：晋国都城体系的演变》，《中原文化研究》2021年第2期","url":"https://www.zywhyj.cn/Uploads/PdfFile/2021-03-16/60506026c2527.pdf"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-jin-chunqiu-quwo','loc-823f1e50fb5d19905068bfa648831034','dynasty','jin-chunqiu','曲沃',NULL,-745,1,NULL,-678,12,NULL,-8928,-8113,'year','year','primary','前745年晋昭侯封成师于曲沃，号桓叔；曲沃为其封邑及支系治所，当时晋君都翼。桓叔、庄伯、武公三世以曲沃为据点与翼公室争位；前739年桓叔应潘父之邀入晋，遭晋人反击后退回曲沃；前678年武公代翼并受周王册命为晋侯。古曲沃据上郭城址及邱家庄墓群考古研究比定于今闻喜县，并非现代曲沃县。代翼后曲沃仍为宗庙所在地。曲沃为曲沃支系治所。','[{"label":"《史记》卷三十九·晋世家：翼都、曲沃封邑与献公都绛","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：天马—曲村、上郭—邱家庄与侯马新田","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"},{"label":"山东大学考古讲座：田建文《唐封晋霸西东周》，古曲沃非今曲沃","url":"https://klast.sdu.edu.cn/info/1031/1673.htm"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-jin-chunqiu-xinjiang-585','loc-3d5043964471fd257a273845e0c118f8','dynasty','jin-chunqiu','新田/新绛',NULL,-585,1,NULL,-349,12,NULL,-7008,-4165,'year','year','primary','晋景公于前585年迁都新田，亦称新绛，故址为今侯马晋国遗址。','[{"label":"《左传·成公六年》：晋景公迁都新田","url":"https://zh.wikisource.org/wiki/春秋左氏傳/成公"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：天马—曲村、上郭—邱家庄与侯马新田","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-jin-chunqiu-yi','loc-09f3c173ba489602bebbd62253d859ec','dynasty','jin-chunqiu','翼',NULL,-745,1,NULL,-669,12,NULL,-8928,-8005,'year','year','primary','晋国在西周时期已有早期都邑。曲村—天马遗址发现西周早期遗存与连续的晋侯墓地，是早期晋国政治中心；山西大学考古资料将其对应为早期晋都“翼”，翼的确切城址及始用年代仍有争议。前745年昭侯封成师于曲沃时，《史记》明确记翼为晋君都邑，曲沃桓叔、庄伯、武公随后与翼城公室并立。曲沃代翼后，《史记》记晋武公“始都晋国”，献公八年（前669年）“城聚都之，命曰绛”。另有将翼考定在今翼城县南梁镇故城村一带的说法。','[{"label":"《史记》卷三十九·晋世家：叔虞封唐、燮改号晋与昭侯时翼都","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：西周早期晋都、燮父至文侯墓葬序列与三处都邑遗址","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"},{"label":"潘明娟《圣都与俗都：晋国都城体系的演变》，《中原文化研究》2021年第2期","url":"https://www.zywhyj.cn/Uploads/PdfFile/2021-03-16/60506026c2527.pdf"},{"label":"上海博物馆《晋侯墓地》：曲村—天马早期晋都及西周晋侯墓葬","url":"https://www.shanghaimuseum.net/mu/asset2/20151230150415016/"}]');
