INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-jin-hou-taiyuan-936','loc-91b731e0771362127a8e9b8445a5d4c2','dynasty','jin-hou','汴州',NULL,938,1,NULL,947,1,16,11256,11364,'year','day','primary','后晋初据洛阳，938年迁都汴州，947年为契丹所灭；迁都月份为原历十月，未直接写作公历十月。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/后晋"},{"label":"复旦大学中国历史地理数据库：938年迁都汴州","url":"https://tgaz.fudan.edu.cn/tgaz/placename/hvd_44315"}]');
