INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-jin-west-changan-304','loc-bdbe217d58d2becb8018927319f45679','dynasty','jin-west','长安',NULL,304,1,NULL,306,6,10,3648,3677,'year','day','temporary','永安元年（304）张方挟持晋惠帝司马衷及公卿至长安，司马颙以征西府为宫；惠帝于306年6月11日还洛阳。洛阳留台仍承制行事，故此处记长安为短期朝廷实际驻地（行在），洛阳仍保留西晋京师都城记录。','[{"label":"《晋书·惠帝纪》","url":"https://www.shidianguji.com/book/LS0005/chapter/LS0005_52"},{"label":"陕西省地方志：西安市志","url":"https://dfz.shaanxi.gov.cn/zslm/fzzlk/xbsxsxz/xbsxz/xas_16198/201405/P020240923625160882829.pdf"},{"label":"中国人民大学清史研究所：先秦至明代地理研究（引《西安历史地图集》）","url":"https://iqh.ruc.edu.cn/old/zglsdlyj/lsdl_lzjj/xqzmddlyj/490272705243483b96edc6a7eea546cd.htm"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-jin-west-changan-313','loc-bdbe217d58d2becb8018927319f45679','dynasty','jin-west','长安',NULL,313,6,12,316,12,11,3761,3803,'day','day','primary','司马业于313年6月12日在长安即位，西晋朝廷以长安为都；316年12月11日司马业向刘曜出降，西晋都城阶段结束。日期与司马业在位记录一致。','[{"label":"《晋书》卷五·愍帝纪","url":"https://www.shidianguji.com/book/HY3000/chapter/1kr3u6p11dkwr"},{"label":"中国地情网：司马邺于长安即位，以长安为都","url":"https://zhongguodiqing.cn/gjmr/201909/t20190924_4976541.shtml"},{"label":"陕西地方志：晋愍帝建兴元年即位于长安","url":"https://dfz.shaanxi.gov.cn/zslm/fzzlk/xbsxsz/szdylpdf/201404/P020240923616206405975.pdf"}]');
