INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-shang-ao-secondary-1419','loc-bb89088fdb33e146c8c221eea977ba9c','dynasty','shang','隞/嚣','郑州市约略点；隞的具体地望有争议',-1419,1,NULL,-1401,12,NULL,-17016,-16789,'year','year','secondary','中丁迁隞（又作嚣/敖）后，此地为商王室辅都之一；具体遗址地望有争议，郑州一带为一种考古解释。郑州亳都在这一时期仍延续。','[{"label":"全国哲学社会科学工作办公室：张国硕《中国早期都城的设都制度》","url":"https://www.nopss.gov.cn/n1/2021/0113/c430752-31997972.html"},{"label":"河南博物院：《商代的都城有几个？它们都在河南的什么地方？》","url":"https://www.chnmus.net/clzl/2011-12/20/content_3611.htm"},{"label":"《史记·殷本纪》","url":"https://ctext.org/shiji/yin-ben-ji/zh"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-shang-bi-secondary-1391','loc-shang-bi-yuncheng-approx','dynasty','shang','庇','郓城县区域示意点，非考古遗址定位；庇地望有争议',-1391,1,NULL,-1330,12,NULL,-16680,-15937,'year','year','secondary','祖乙居庇，祖辛、沃甲、祖丁承用庇地的传世记载见《古本竹书纪年》系统；Wiki 所列沃甲都庇与该世系相符。庇常被考定为今郓城县境，但具体故址及庇、邢、耿异名关系仍有争议。','[{"label":"沃甲","url":"https://zh.wikipedia.org/wiki/沃甲"},{"label":"庇（所据古本《竹书纪年》及地望考证）","url":"https://zh.wikipedia.org/wiki/庇"},{"label":"郓城县地方志：地理位置与庇故址","url":"https://shandong-chorography.org/database/bh/section/1/article/18/"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-shang-bo-primary-1600','loc-bb89088fdb33e146c8c221eea977ba9c','dynasty','shang','亳','郑州商城遗址所在城市约略点；亳的地望存在学术争议',-1600,1,NULL,-1301,12,NULL,-19188,-15589,'year','year','primary','商前期以亳为主都，东部、北部另有王室活动中心。有考古研究将早商亳比定为郑州商城；其具体地望及商丘、偃师等说仍有争议。','[{"label":"全国哲学社会科学工作办公室：张国硕《中国早期都城的设都制度》","url":"https://www.nopss.gov.cn/n1/2021/0113/c430752-31997972.html"},{"label":"河南博物院：《商代的都城有几个？它们都在河南的什么地方？》","url":"https://www.chnmus.net/clzl/2011-12/20/content_3611.htm"},{"label":"商朝君主列表（都城与夏商周断代工程年表）","url":"https://zh.wikipedia.org/wiki/商朝君主列表"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-shang-xiang-secondary-1400','loc-7575495d7526cb46127984392d92bd76','dynasty','shang','相','内黄县区域约略点；遗址未能确证',-1400,1,NULL,-1392,12,NULL,-16788,-16681,'year','year','secondary','传世文献载河亶甲居相。现有研究将相地望约定在今河南内黄一带，尚无对应商代都城遗址的充分考古确认；此条表示辅都，不覆盖郑州亳主都。','[{"label":"全国哲学社会科学工作办公室：张国硕《中国早期都城的设都制度》","url":"https://www.nopss.gov.cn/n1/2021/0113/c430752-31997972.html"},{"label":"河南博物院：《商代的都城有几个？它们都在河南的什么地方？》","url":"https://www.chnmus.net/clzl/2011-12/20/content_3611.htm"},{"label":"《史记·殷本纪》","url":"https://ctext.org/shiji/yin-ben-ji/zh"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-shang-yan-secondary-1329','loc-d0f912cc274515214338b7c96ffce31f','dynasty','shang','奄','曲阜市约略点',-1329,1,NULL,-1311,12,NULL,-15936,-15709,'year','year','secondary','南庚迁都于奄，后阳甲沿用；奄的传统地望在今山东曲阜附近。辅都设置期间，商前期主都亳仍延续。','[{"label":"全国哲学社会科学工作办公室：张国硕《中国早期都城的设都制度》","url":"https://www.nopss.gov.cn/n1/2021/0113/c430752-31997972.html"},{"label":"河南博物院：《商代的都城有几个？它们都在河南的什么地方？》","url":"https://www.chnmus.net/clzl/2011-12/20/content_3611.htm"},{"label":"《史记·殷本纪》","url":"https://ctext.org/shiji/yin-ben-ji/zh"},{"label":"商朝君主列表（都城与夏商周断代工程年表）","url":"https://zh.wikipedia.org/wiki/商朝君主列表"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-shang-yin-primary-1300','loc-21798e9ca7e2d2124da0f0a34e2bd98f','dynasty','shang','殷','殷墟遗址约略点',-1300,1,NULL,-1046,12,NULL,-15588,-12529,'year','year','primary','盘庚迁殷后，以殷墟一带为商后期主都，延续至商亡；迁殷约前1300年，具体年份在传世年表间有差异。','[{"label":"全国哲学社会科学工作办公室：张国硕《中国早期都城的设都制度》","url":"https://www.nopss.gov.cn/n1/2021/0113/c430752-31997972.html"},{"label":"河南博物院：《商代的都城有几个？它们都在河南的什么地方？》","url":"https://www.chnmus.net/clzl/2011-12/20/content_3611.htm"},{"label":"《史记·殷本纪》","url":"https://ctext.org/shiji/yin-ben-ji/zh"},{"label":"商朝君主列表（都城与夏商周断代工程年表）","url":"https://zh.wikipedia.org/wiki/商朝君主列表"}]');
