INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-yan-anshi-fanyang-755','loc-ea36bf10f6f624664cffe9590c9bef79','dynasty','yan-anshi','范阳',NULL,755,12,16,756,1,17,9071,9072,'day','day','primary','安禄山于范阳起兵，初期军政中心在此。安军于天宝十四载十二月丁酉（十二日）攻取洛阳，按《资治通鉴》卷217与中国历代朔闰表换算为公历756-01-18，故范阳阶段止于前一日；此记录表示起兵初期的主治所，不将起兵地点等同于称帝后的正式都城。','[{"label":"《资治通鉴》卷二百十七：安禄山反于范阳、十二月陷洛阳","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷217"},{"label":"中国历代朔闰表（唐、五代）：天宝十四载十二月日期换算","url":"https://ytliu0.github.io/ChineseCalendar/table_period_simp.html?period=tang5"},{"label":"故宫博物院：安禄山","url":"https://www.dpm.org.cn/lemmas/243350.html"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-yan-anshi-fanyang-759','loc-ea36bf10f6f624664cffe9590c9bef79','dynasty','yan-anshi','范阳/燕京',NULL,759,4,7,759,9,26,9111,9116,'approximate_day','day','primary','史思明杀安庆绪后返回范阳，并于乾元二年四月在范阳称帝、改称燕京；称帝具体公历日未能据可靠历日确定，起点以安庆绪被杀日作为接续标记并标推定。759年九月史军重新进入洛阳，主都阶段止于入城前一日。','[{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"},{"label":"北京日报：史思明建“都”范阳城","url":"https://peking.bjd.com.cn/content/s63a524c9e4b0450519f694a7.html"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-yan-anshi-fanyang-secondary-759','loc-ea36bf10f6f624664cffe9590c9bef79','dynasty','yan-anshi','范阳/燕京',NULL,759,4,7,763,1,30,9111,9156,'approximate_day','approximate_day','secondary','史思明称帝后改范阳为燕京；759年洛阳复入后范阳保留为燕京/后方政治中心，至史朝义败亡前后失去政权控制。末端依史朝义败亡、首级入京的时间范围标推定。','[{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"},{"label":"《资治通鉴》卷222","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷222"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-yan-anshi-luoyang-756','loc-f7e930313c1cb946efe0973a87515dd4','dynasty','yan-anshi','洛阳',NULL,756,2,5,757,10,17,9073,9093,'day','day','primary','安禄山于洛阳称帝并以此为政权中心；757年唐军收复洛阳后，安庆绪退保邺城。','[{"label":"《安禄山事迹》卷下","url":"https://zh.wikisource.org/zh-hans/安祿山事跡/卷下"},{"label":"《资治通鉴》卷219","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷219"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-yan-anshi-luoyang-759','loc-f7e930313c1cb946efe0973a87515dd4','dynasty','yan-anshi','洛阳/周京',NULL,759,9,27,762,10,29,9116,9153,'day','day','primary','史思明军759年九月再入洛阳后，以洛阳为周京；762年唐军收复洛阳，止于失守前一日。地点名称原注：洛阳（周京）。','[{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"},{"label":"《资治通鉴》卷222","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷222"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-yan-anshi-luoyang-preaccession-756','loc-f7e930313c1cb946efe0973a87515dd4','dynasty','yan-anshi','洛阳',NULL,756,1,18,756,2,4,9072,9073,'day','day','primary','安军于天宝十四载十二月丁酉（十二日）攻取洛阳，按《资治通鉴》卷217与中国历代朔闰表换算为公历756-01-18；安禄山其后在此筹备并于至德元载正月称帝。此为称帝前的洛阳主治所阶段，终止于正式即位前一日。','[{"label":"《资治通鉴》卷二百十七：天宝十四载十二月安军陷洛阳","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷217"},{"label":"中国历代朔闰表（唐、五代）：天宝十四载十二月日期换算","url":"https://ytliu0.github.io/ChineseCalendar/table_period_simp.html?period=tang5"},{"label":"《安禄山事迹》卷下：至德元载正月乙卯朔安禄山在洛阳称帝","url":"https://zh.wikisource.org/zh-hans/安祿山事跡/卷下"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('cap-yan-anshi-ye-757','loc-806658dc845429fdd4d9971880684542','dynasty','yan-anshi','邺/安成府',NULL,757,10,18,759,4,6,9093,9111,'day','day','primary','安庆绪弃洛阳后退保邺郡，改邺郡为安成府；史思明杀安庆绪并接收其军后，该政权中心转至范阳。地点名称原注：邺（安成府）。','[{"label":"《资治通鉴》卷219","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷219"},{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"}]');
